contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We drive deposit with arbitrary caller by having this contract call it.
    // Use a parameter `amt` as the value sent. The call must not revert on the original contract P
    // for any amt >= 0, but the mutant M can revert when amt == 0 in some states.
    function run(uint256 amt) public payable {
        // Ensure this test harness has enough balance to forward the amount
        require(address(this).balance >= amt);

        bool reverted;
        try c.deposit{value: amt}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: in the original contract P, deposit never reverts for any caller and any amt >= 0.
        // We assert that the call did not revert. This holds for P but is violated by the mutant M on some inputs.
        assert(!reverted);
    }

    receive() external payable {}
}

