contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: provide depositor address as msg.sender via call context
    // amount is the value to send to deposit
    function checkDepositIncrease(uint256 amount) public payable {
        // need enough ether in this contract to send
        require(address(this).balance >= amount);
        // read old contract balance for this test caller via fallback: C has no getter for balances so we observe effect via withdraw attempt
        // To observe the stored per-address balance we use the following approach:
        // 1) Make a deposit of `amount` via c.deposit{value: amount}()
        // 2) Then attempt to withdraw more than the deposited amount (old + amount - 1) to detect whether stored balance increased appropriately.
        // But withdraw reverts if amount > balances[msg.sender]. So we can use that revert boolean returned by low-level call to test the invariant.

        // First, capture whether withdrawing (amount) BEFORE deposit would succeed: should be false (no funds yet)
        (bool preOk,) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", amount));

        // perform the deposit
        c.deposit{value: amount}();

        // Now try to withdraw `amount` again. On correct contract P the withdrawal should succeed; on mutant M it may still succeed in many cases, so to make a general rule
        // we instead assert that the post-deposit withdrawal of (amount) succeeds iff the pre-deposit withdrawal failed -> this captures that the deposit increased caller's balance by at least amount.
        (bool postOk,) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", amount));

        // The invariant: if pre-deposit withdraw failed (preOk == false), then post-deposit withdraw must succeed (postOk == true).
        // This is a single comparison over observed revert booleans.
        assert((preOk == true) || (postOk == true));
    }

    // allow contract to hold Ether for sending deposits
    receive() external payable {}
}

