        vm.assume(depositor != address(0));

        // Ensure depositor has enough ETH to send
        vm.deal(depositor, amount);

        // Read prior recorded balance via the public mapping getter
        uint256 before = getBalance(depositor);

        // We restrict to the admissible domain where addition does NOT overflow
        // i.e., before + amount <= type(uint256).max
        // This avoids the overflow case which the reference's assert prevents; in this domain
        // the reference must always succeed and increase balance by exactly amount.
        vm.assume(before + amount >= before); // trivial but keeps expression readable
        vm.assume(type(uint256).max - before >= amount);

        // Make the deposit from the depositor
        vm.prank(depositor);
        c.deposit{value: amount}();

        // Exactly one assertion: after deposit, recorded balance equals before + amount.
        uint256 after = getBalance(depositor);
        assertTrue(after == before + amount);
    }

    // Helper to access the public mapping (balances) getter
    function getBalance(address a) internal view returns (uint256) {
        // The original contract's mapping is named `balances` (not public in source),
