import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero to be a canonical actor, but allow wide domain
        vm.assume(depositor != address(0));
        // fund the depositor so they can send Ether
        vm.deal(depositor, amount);

        // record prior stored balance via the public getter: balances is not public in original
        // but we can observe address(c).balance as a coarse measure; however rule targets per-depositor stored balance
        // The contract C has a private mapping balances, no getter — so we must observe behavior via deposits and refunds.
        // To read depositor's recorded balance we exploit withdraw: withdraw requires amount <= balances[msg.sender].
        // We'll first deposit a known baseline, then attempt to withdraw that baseline to discover stored balance bounds.

        // Step A: make an initial small deposit to establish baseline (if amount==0 this is no-op)
        if (amount > 0) {
            vm.prank(depositor);
            c.deposit{value: 1}();
        }

        // Try to discover previous stored balance by attempting to withdraw amounts using a binary-ish probe is too heavy for one assert.
        // Instead, we assert a monotonicity property: after a deposit that returns successfully, the stored balance for depositor is not less than before.
        // We observe this by performing deposit twice: between them we try to withdraw 0 (no-op) to avoid changing state.

        // Record contract balance and depositor-visible withdrawability before second deposit by attempting a zero withdraw via try/catch.
        // But withdraw of 0 is permitted; it will transfer 0 and do balances[msg.sender] -= 0 (no-op).
        // Therefore we cannot change the stored balance. To get prior stored info, we use the fact that withdraw reverts if amount > balances.
        // We'll probe whether a large amount (2**255) is withdrawable before and after deposit via try/catch to detect if balances decreased below that threshold.

        uint256 probe = type(uint256).max / 2;

        bool okBefore;
        vm.prank(depositor);
        try c.withdraw(probe) {
            // If withdraw succeeded, the contract transferred funds; but we don't want to change state. To avoid state change, only consider success as ok.
            okBefore = true;
            // if it withdrew, the balances decreased; to keep invariants simple we restore by depositing back any drained ether
            // but in most cases this won't occur because probe is huge
        } catch {
            okBefore = false;
        }

        // Now perform the fuzzed deposit
        vm.prank(depositor);
        c.deposit{value: amount}();

        bool okAfter;
        vm.prank(depositor);
        try c.withdraw(probe) {
            okAfter = true;
        } catch {
            okAfter = false;
        }

        // General property: depositing cannot make previously-withdrawable large amounts become non-withdrawable due to wraparound
        // i.e., okBefore implies okAfter (if before we could withdraw a huge amount, after deposit we should still be able to withdraw it)
        // This captures that balances did not decrease as a result of deposit. The reference satisfies this for all inputs; the mutant can fail.
        assertTrue(!okBefore || okAfter);
    }
}

