import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: an actor address and two deposit amounts.
    // We need at least one parameter; we use three to let the fuzzer find a sequence
    // where the actor first makes a (possibly larger) deposit and then a second deposit
    // that exposes the overwrite bug in the mutant. The property we assert is:
    // after any deposit by an actor of a positive amount, the recorded balance for that
    // actor is >= the amount just deposited. The reference C (which adds) always
    // satisfies this; the mutant that sets balances[actor] = msg.value can violate it
    // when the actor had a prior larger balance and then deposits a smaller amount.
    function testFuzz_property(address actor, uint256 firstAmount, uint256 secondAmount) public {
        // Keep actor non-zero and amounts bounded to reasonable values and nonzero for second deposit
        vm.assume(actor != address(0));
        firstAmount = bound(firstAmount, 0, 1 ether);
        secondAmount = bound(secondAmount, 1, 1 ether); // require second deposit > 0 so effect is meaningful

        // Fund actor so they can send ETH
        vm.deal(actor, firstAmount + secondAmount + 1 wei);

        // Actor makes an initial deposit (may be zero)
        vm.prank(actor);
        c.deposit{value: firstAmount}();

        // Actor makes the second deposit which we will inspect
        vm.prank(actor);
        c.deposit{value: secondAmount}();

        // The universal property: after a deposit of `secondAmount` (which is >=1),
        // the recorded balance for actor must be >= secondAmount. Reference C (which
        // adds) guarantees balances[actor] >= secondAmount for all inputs; the mutant
        // that overwrites can produce balances < secondAmount when firstAmount > secondAmount.
        // Read the contract's observable: address(c).balance is allowed, but we need the per-actor
        // balance; the mapping is internal so no getter — however the difference can be observed
        // indirectly by calling refund() which transfers balances[actor] to actor and zeroes it.
        // We'll call refund() and check that the refunded amount (via actor's balance change)
        // is >= secondAmount. To observe the refunded amount we check the actor's eth balance
        // before/after the refund call.

        // Record pre-refund balance of actor
        uint256 before = actor.balance;

        // Have actor call refund() to receive their recorded balance
        vm.prank(actor);
        c.refund();

        uint256 after = actor.balance;
        uint256 refunded = after - before;

        // Single assertion reading c's public behavior: the refunded amount must be >= secondAmount.
        // This holds for the reference (which accumulates balances) for all admissible inputs,
        // but the mutant that overwrites can make refunded < secondAmount when firstAmount > secondAmount.
        assertTrue(refunded >= secondAmount);
    }
}

